  const v18ProvBadge = document.getElementById("v18-prov-badge");
  const v18ProvPreset = document.getElementById("v18-prov-preset");
  const v18ProvBtn = document.getElementById("v18-prov-eval-btn");
  const v18ProvSummary = document.getElementById("v18-prov-summary");
  const v18ProvKpi = document.getElementById("v18-prov-kpi");
